const wchar_t* WindowsZoneId(std::string_view iana) {
    auto it = std::lower_bound(std::begin(kZones), std::end(kZones), iana,
                               [](const WindowsZoneEntry& e, std::string_view v) { return e.iana < v; });
    return (it != std::end(kZones) && it->iana == iana) ? it->windows : nullptr;
}

std::span<const WindowsZoneEntry> AllWindowsZones() { return kZones; }
